import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  [
    // Labels wrap to two lines (no whitespace-nowrap) and the sizes below use
    // min-h, not a fixed height, so a long label -- common in translated UIs --
    // breaks inside the button instead of overflowing it. text-center keeps a
    // wrapped label centered.
    "inline-flex items-center justify-center gap-2 text-center",
    "text-sm font-medium transition-all duration-200",
    "wj-focus-ring",
    "disabled:pointer-events-none disabled:opacity-50",
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ],
  {
    variants: {
      variant: {
        default: [
          "bg-[var(--color-neutral-900)] text-white",
          // Inverted fill: near-black in light mode, white in dark, so the
          // bevel that matches the SURFACE is the opposite of the theme's.
          "shadow-bevel-dark dark:shadow-bevel-light",
          "hover:bg-[var(--color-neutral-800)]",
          "dark:bg-white dark:text-[var(--color-neutral-900)]",
          "dark:hover:bg-[var(--color-neutral-100)]",
        ],
        secondary: [
          // The bordered tier: no fill, so it reads as the quieter half of a
          // pair with accent. Border rather than bevel, per the border-XOR-bevel
          // rule.
          "border border-[var(--color-border-light)] bg-transparent",
          "text-[var(--color-text-primary-light)]",
          "hover:bg-[var(--color-surface-muted-light)]",
          "hover:border-[var(--color-warm-300)]",
          "dark:border-[var(--color-border-dark)]",
          "dark:text-[var(--color-text-primary-dark)]",
          "dark:hover:bg-[var(--color-surface-muted-dark)]",
          "dark:hover:border-[var(--color-neutral-700)]",
        ],
        selection: [
          // A button that reads as a SELECTABLE surface rather than an action:
          // the same muted fill and bevel an unselected ToggleGroup tile and an
          // active nav item carry. `aria-pressed` drives the chosen state,
          // which fills with the accent -- so the visual state and the state
          // assistive tech reads are the same attribute, not two that can drift.
          "bg-[var(--color-surface-muted-light)] shadow-bevel",
          "text-[var(--color-text-secondary-light)]",
          "hover:bg-[var(--color-warm-200)]",
          "dark:bg-[var(--color-surface-muted-dark)]",
          "dark:text-[var(--color-text-secondary-dark)]",
          "dark:hover:bg-[var(--color-neutral-700)]",
          "aria-pressed:bg-[var(--color-accent-500)] aria-pressed:text-[var(--color-accent-foreground)]",
          "aria-pressed:shadow-bevel-accent",
        ],
        ghost: [
          "hover:bg-[var(--color-neutral-100)]",
          // No border to fall back on, so on a Card this was a button with no
          // hover feedback at all in dark mode.
          "dark:hover:bg-[var(--color-surface-muted-dark)]",
        ],
        destructive: [
          "bg-[var(--color-error-500)] text-white",
          "shadow-bevel-accent",
          "hover:bg-[var(--color-error-700)]",
        ],
        accent: [
          "bg-[var(--color-accent-500)] text-[var(--color-accent-foreground)]",
          "shadow-bevel-accent",
          "hover:bg-[var(--color-accent-400)]",
          "active:bg-[var(--color-accent-600)]",
        ],
        link: [
          "text-[var(--color-neutral-900)] underline-offset-4",
          "hover:underline",
          "dark:text-white",
        ],
      },
      size: {
        // min-h (not h) so the button grows to fit a wrapped two-line label;
        // icon is a fixed square (no text, never wraps). The scale is the
        // shared control heights, so a Button, an Input and a Select set beside
        // each other line up without any of the three naming a number.
        sm: "min-h-control-sm rounded-full px-3 py-1 text-xs",
        default: "min-h-control-md rounded-full px-6 py-2",
        md: "min-h-control-md rounded-full px-6 py-2",
        lg: "min-h-control-lg rounded-full px-8 py-2 text-base",
        icon: "h-control-md w-control-md rounded-full",
        "icon-sm": "h-control-sm w-control-sm rounded-full",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /**
   * Render the button styling onto the single child element instead of a
   * `<button>` -- the way to make link-buttons without nesting interactive
   * elements: `<Button asChild><Link to="/x">Go</Link></Button>`. The child's
   * own props win on conflict; classNames merge.
   */
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, children, ...props }, ref) => {
    const classes = cn(buttonVariants({ variant, size, className }));
    if (asChild) {
      // Minimal slot (no Radix dependency): clone the single child with the
      // button classes and remaining props merged in.
      const child = React.Children.only(children) as React.ReactElement<
        Record<string, unknown>
      >;
      const mergedProps: Record<string, unknown> = {
        ...props,
        ...child.props,
        className: cn(classes, child.props.className as string | undefined),
        ref,
      };
      return React.cloneElement(child, mergedProps);
    }
    return (
      <button className={classes} ref={ref} {...props}>
        {children}
      </button>
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };
